From 2463ddd4c2403a9e8ac322638a47e42d704d5aef Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:15:23 +0100
Subject: [PATCH] klipper: show the dragged item under the cursor

Dragging an entry out of the clipboard popup gave no visual feedback
other than the cursor, so it wasn't clear what was being dragged. Now the
entry's text, image or file previews are used as the drag image instead.

BUG: 478586
---
 .../declarative/qml/ClipboardItemDelegate.qml   | 17 +++++++++++++++++
 klipper/declarative/qml/ImageItemDelegate.qml   |  1 -
 klipper/declarative/qml/TextItemDelegate.qml    |  1 -
 klipper/declarative/qml/UrlItemDelegate.qml     |  1 -
 4 files changed, 17 insertions(+), 3 deletions(-)

diff --git a/klipper/declarative/qml/ClipboardItemDelegate.qml b/klipper/declarative/qml/ClipboardItemDelegate.qml
index 58df3a6008..abba97af0c 100644
--- a/klipper/declarative/qml/ClipboardItemDelegate.qml
+++ b/klipper/declarative/qml/ClipboardItemDelegate.qml
@@ -109,6 +109,23 @@ PlasmaComponents.ItemDelegate {
         id: dragHandler
         enabled: !(toolButtonsLoader.item as DelegateToolButtons)?.hovered
         target: null
+
+        onActiveChanged: {
+            const dragItem = menuItem.mainItem;
+            if (!active) {
+                dragItem.Drag.active = false;
+                dragItem.Drag.imageSource = "";
+                return;
+            }
+            dragItem.Drag.hotSpot = dragItem.mapFromItem(menuItem, centroid.pressPosition);
+            dragItem.grabToImage(result => {
+                if (!dragHandler.active) {
+                    return;
+                }
+                dragItem.Drag.imageSource = result.url;
+                dragItem.Drag.active = true;
+            });
+        }
     }

     // this stuff here is used so we can fade out the text behind the tool buttons
diff --git a/klipper/declarative/qml/ImageItemDelegate.qml b/klipper/declarative/qml/ImageItemDelegate.qml
index fdbb0c9a7a..63253c2a34 100644
--- a/klipper/declarative/qml/ImageItemDelegate.qml
+++ b/klipper/declarative/qml/ImageItemDelegate.qml
@@ -16,7 +16,6 @@ ClipboardItemDelegate {
     mainItem: Item {
         implicitHeight: childrenRect.height

-        Drag.active: menuItem.dragHandler.active
         Drag.dragType: Drag.Automatic
         Drag.supportedActions: Qt.CopyAction
         Drag.mimeData: {
diff --git a/klipper/declarative/qml/TextItemDelegate.qml b/klipper/declarative/qml/TextItemDelegate.qml
index 191b89d803..db7237c05d 100644
--- a/klipper/declarative/qml/TextItemDelegate.qml
+++ b/klipper/declarative/qml/TextItemDelegate.qml
@@ -56,7 +56,6 @@ ClipboardItemDelegate {

         Accessible.ignored: true

-        Drag.active: menuItem.dragHandler.active
         Drag.dragType: Drag.Automatic
         Drag.supportedActions: Qt.CopyAction
         Drag.mimeData: {
diff --git a/klipper/declarative/qml/UrlItemDelegate.qml b/klipper/declarative/qml/UrlItemDelegate.qml
index 8c5d842b31..feca82bf8a 100644
--- a/klipper/declarative/qml/UrlItemDelegate.qml
+++ b/klipper/declarative/qml/UrlItemDelegate.qml
@@ -21,7 +21,6 @@ ClipboardItemDelegate {
         id: previewItem
         implicitHeight: Kirigami.Units.gridUnit * 4 + Kirigami.Units.smallSpacing * 2

-        Drag.active: menuItem.dragHandler.active
         Drag.dragType: Drag.Automatic
         Drag.supportedActions: Qt.CopyAction
         Drag.mimeData: {
